	/** @param array<string,string> $keys */public function __construct(string $root,array $keys,string $currentKeyId,?callable $authorizer=null,?callable $clock=null,int $retention=10000){if($keys===[]){throw new \InvalidArgumentException('Compliance ledger requires a signing keyring.');}$normalized=[];foreach($keys as$id=>$key){$id=PanelOperationsGuard::name((string)$id,'compliance key id');if(!is_string($key)||strlen($key)<32){throw new \InvalidArgumentException('Compliance keys require at least 32 bytes.');}$normalized[$id]=$key;}$currentKeyId=PanelOperationsGuard::name($currentKeyId,'current compliance key id');if(!isset($normalized[$currentKeyId])){throw new \InvalidArgumentException('Current compliance key is not trusted.');}$this->keys=$normalized;$this->currentKeyId=$currentKeyId;$this->evidenceRetention=max(100,$retention);$this->authorizer=$authorizer!==null?\Closure::fromCallable($authorizer):null;$this->clock=$clock!==null?\Closure::fromCallable($clock):static fn():string=>gmdate('c');$initial=['schema'=>'panel_compliance_ledger','version'=>1,'sequence'=>0,'anchor_hash'=>str_repeat('0',64),'controls'=>[],'evidence'=>[],'holds'=>[]];$this->store=new PanelAtomicSnapshotStore($root,'panel.compliance-ledger.v1',$initial,max(8,$retention));$this->assertState($this->store->payload());}
