	/** @return array<string,array<string,mixed>> */ public function controls():array {$state=$this->store->payload();$this->assertState($state);return$state['controls'];}
	/** @return array<string,mixed>|null */ public function control(string $id):?array {$id=PanelOperationsGuard::name($id,'compliance control id');return$this->controls()[$id]??null;}
