	public function hold(string $holdId,string $reason,string|int $actorId,?string $controlId=null):array {$holdId=PanelOperationsGuard::name($holdId,'legal hold id');$actorId=PanelOperationsGuard::identifier($actorId,'compliance actor id');$reason=PanelOperationsGuard::label($reason,'legal hold reason',2048);if($controlId!==null){$controlId=PanelOperationsGuard::name($controlId,'compliance control id');}$this->authorize('compliance.hold.place',['hold_id'=>$holdId,'actor_id'=>$actorId]);return$this->store->transaction(function(array &$state)use($holdId,$reason,$actorId,$controlId):array{if(isset($state['holds'][$holdId])){throw new \LogicException('Legal hold is already active.');}if($controlId!==null&&!isset($state['controls'][$controlId])){throw new \OutOfBoundsException('Compliance control is not registered.');}$hold=['id'=>$holdId,'reason'=>$reason,'control_id'=>$controlId,'placed_by_hash'=>hash('sha256',$actorId),'placed_at'=>$this->now(),'released_at'=>null];$state['holds'][$holdId]=$hold;return$hold;},'compliance.hold.placed',['hold_id'=>$holdId])['result'];}
	public function releaseHold(string $holdId,string|int $actorId):array {$holdId=PanelOperationsGuard::name($holdId,'legal hold id');$actorId=PanelOperationsGuard::identifier($actorId,'compliance actor id');$this->authorize('compliance.hold.release',['hold_id'=>$holdId,'actor_id'=>$actorId]);return$this->store->transaction(function(array &$state)use($holdId,$actorId):array{$hold=$state['holds'][$holdId]??null;if(!is_array($hold)||$hold['released_at']!==null){throw new \OutOfBoundsException('Active legal hold does not exist.');}$hold['released_at']=$this->now();$hold['released_by_hash']=hash('sha256',$actorId);$state['holds'][$holdId]=$hold;return$hold;},'compliance.hold.released',['hold_id'=>$holdId])['result'];}
	/** @param list<string> $controlIds */public function pack(array $controlIds=[]):PanelComplianceEvidencePack {$state=$this->store->payload();$this->assertState($state);$controlIds=$controlIds===[]?array_keys($state['controls']):PanelOperationsGuard::names($controlIds,'compliance control id');if(array_diff($controlIds,array_keys($state['controls']))!==[]){throw new \OutOfBoundsException('Compliance evidence pack requested an unknown control.');}$controls=array_intersect_key($state['controls'],array_fill_keys($controlIds,true));$evidence=array_values(array_filter($state['evidence'],static fn(array $event):bool=>in_array($event['control_id'],$controlIds,true)));$holds=array_values(array_filter($state['holds'],static fn(array $hold):bool=>$hold['released_at']===null&&($hold['control_id']===null||in_array($hold['control_id'],$controlIds,true))));$payload=['generated_at'=>$this->now(),'sequence'=>$state['sequence'],'controls'=>$controls,'evidence'=>$evidence,'active_holds'=>$holds,'ledger_verified'=>true,'latest_hash'=>$evidence!==[]?$evidence[array_key_last($evidence)]['hash']:$state['anchor_hash']];return PanelComplianceEvidencePack::sign($payload,$this->currentKeyId,$this->keys[$this->currentKeyId]);}
	public function verify():bool {try{$this->assertState($this->store->payload());return true;}catch(\Throwable){return false;}}public function jsonSerialize():array{$state=$this->store->payload();return PanelManifestContract::stamp(['type'=>'panel_compliance_ledger_manifest','version'=>1,'sequence'=>$state['sequence'],'control_count'=>count($state['controls']),'evidence_count'=>count($state['evidence']),'evidence_retention'=>$this->evidenceRetention,'active_hold_count'=>count(array_filter($state['holds'],static fn(array $hold):bool=>$hold['released_at']===null)),'key_ids'=>array_keys($this->keys),'current_key_id'=>$this->currentKeyId,'default_deny'=>$this->authorizer===null,'capabilities'=>['continuous_evidence'=>true,'typed_observations'=>true,'automated_collection_runs'=>true,'tamper_evident_chain'=>true,'signed_evidence_packs'=>true,'signed_collection_runs'=>true,'legal_holds'=>true,'hold_aware_retention'=>true,'atomic_persistence'=>true,'key_rotation'=>true]]);}
	/** @param array<string,mixed> $state */private function prune(array &$state):void {$held=[];$global=false;foreach($state['holds']as$hold){if(!is_array($hold)||($hold['released_at']??null)!==null){continue;}if(($hold['control_id']??null)===null){$global=true;break;}$held[(string)$hold['control_id']]=true;}while(!$global&&count($state['evidence'])>$this->evidenceRetention){$id=array_key_first($state['evidence']);$event=$state['evidence'][$id];if(isset($held[(string)$event['control_id']])){break;}$state['anchor_hash']=(string)$event['hash'];unset($state['evidence'][$id]);}}
